+// Generated by offramp web scaffold from src/Shop.Web/Modules/RequestTimingModule.cs.
+using System.Threading.Tasks;
+using Microsoft.AspNetCore.Http;
+
+namespace Shop.Web.Middleware
+{
+    /// <summary>
+    /// The Shop.Web.Modules.RequestTimingModule HttpModule's place in the pipeline. Port its BeginRequest work
+    /// before the call to the next middleware and its EndRequest work after; the original
+    /// is below the namespace, not compiled.
+    /// </summary>
+    public sealed class RequestTimingMiddleware
+    {
+        private readonly RequestDelegate _next;
+
+        public RequestTimingMiddleware(RequestDelegate next)
+        {
+            _next = next;
+        }
+
+        public async Task InvokeAsync(HttpContext context)
+        {
+            await _next(context);
+        }
+    }
+}
+
+#if OFFRAMP_HTTPMODULE // The original HttpModule, to port into InvokeAsync:
+using System;
+using System.Diagnostics;
+using System.Web;
+
+namespace Shop.Web.Modules
+{
+    public class RequestTimingModule : IHttpModule
+    {
+        public void Init(HttpApplication context)
+        {
+            context.BeginRequest += (sender, e) => ((HttpApplication)sender).Context.Items["timer"] = Stopwatch.StartNew();
+            context.EndRequest += (sender, e) =>
+            {
+                var application = (HttpApplication)sender;
+                var timer = (Stopwatch)application.Context.Items["timer"];
+                application.Response.AppendHeader("X-Elapsed-Ms", timer.ElapsedMilliseconds.ToString());
+            };
+        }
+
+        public void Dispose()
+        {
+        }
+    }
+}
+#endif
