+// Generated by offramp web scaffold: the ASP.NET Core front of src/Shop.Web/Shop.Web.csproj. What it does not serve goes to the legacy application.
+using Microsoft.AspNetCore.Builder;
+using Microsoft.Extensions.DependencyInjection;
+
+var builder = WebApplication.CreateBuilder(args);
+
+builder.Services.AddControllersWithViews();
+builder.Services.AddReverseProxy().LoadFromConfig(builder.Configuration.GetSection("ReverseProxy"));
+
+var app = builder.Build();
+
+app.UseMiddleware<Shop.Web.Middleware.RequestTimingMiddleware>();
+app.UseRouting();
+// [Authorize] on ported actions needs an authentication scheme: --adapters shares the legacy application's,
+// or add one with builder.Services.AddAuthentication(...) and app.UseAuthentication() here.
+app.UseAuthorization();
+
+app.MapControllerRoute(name: "Catalog", pattern: "catalog/{category}", defaults: new { controller = "Home", action = "Catalog" });
+app.MapControllerRoute(name: "Default", pattern: "{controller=Home}/{action=Index}/{id?}");
+app.MapControllers();
+// OFR4202: until Shop.Web.Handlers.ThumbnailHandler is ported, the proxy sends thumbnail.axd to the legacy application. Then:
+// app.MapMethods("/thumbnail.axd", new[] { "GET" }, Shop.Web.Endpoints.ThumbnailEndpoint.Handle);
+app.MapReverseProxy();
+
+app.Run();
